import base64
try:
    data = base64.b64decode(open("cert.b64").read())
    def parse(b):
        i = 0; out = []
        while i < len(b):
            t = b[i]; i += 1
            l = b[i]; i += 1
            if l & 0x80:
                n = l & 0x7f; l = int.from_bytes(b[i:i+n], "big"); i += n
            v = b[i:i+l]; i += l
            out.append((t, v))
        return out
    cn = [None]
    def walk(b):
        ch = parse(b)
        if len(ch) >= 2 and ch[0][0] == 0x06 and ch[0][1] == bytes([0x55, 4, 3]):
            cn[0] = ch[1][1]
        for t, v in ch:
            if t in (0x30, 0x31):
                walk(v)
    walk(data)
    exp = cn[0].decode()
    got = open("answer.txt").read().strip()
    print("PASS" if got == exp else "FAIL " + repr((got, exp)))
