    while True:
        b = n & 0x7f; n >>= 7
        if n:
            o += bytes([b | 0x80])
        else:
            o += bytes([b]); break
    return o
items = ["alpha", "beta", "gamma-δ", "this is a longer record number four"]
data = b"".join(var(len(s.encode())) + s.encode() for s in items)
